import{_ as i,C as r,o as h,c as E,a3 as t,E as o}from"./chunks/framework.Ba39LDvt.js";const b=JSON.parse('{"title":"模拟、射频与电源路线","description":"以电路、信号与电磁为共同基础，规划上科大的模拟 IC、射频和电力电子学习路径。","frontmatter":{"title":"模拟、射频与电源路线","description":"以电路、信号与电磁为共同基础，规划上科大的模拟 IC、射频和电力电子学习路径。"},"headers":[],"relativePath":"map/analog.md","filePath":"map/analog.md","lastUpdated":1795513256000}'),d={name:"map/analog.md"};function s(l,a,n,c,u,g){const e=r("CourseTable");return h(),E("div",null,[a[0]||(a[0]=t('<h1 id="模拟、射频与电源路线" tabindex="-1">模拟、射频与电源路线 <a class="header-anchor" href="#模拟、射频与电源路线" aria-label="Permalink to &quot;模拟、射频与电源路线&quot;">​</a></h1><p>如果你喜欢分析连续信号、画波形、做近似推导，并愿意把仿真和测量来回对照，这条路线值得尝试。模拟 IC、射频与电源共享电路基础，却各有核心问题：模拟关心精度、噪声和反馈；射频关心传播、匹配与高频非理想；电源关心能量转换、控制、损耗与可靠性。</p><p>不必把三条支线的课全部修完。先打牢共同基础，再选一个能做出闭环的项目。</p><h2 id="按学年安排主线" tabindex="-1">按学年安排主线 <a class="header-anchor" href="#按学年安排主线" aria-label="Permalink to &quot;按学年安排主线&quot;">​</a></h2><p>基础学期依据 2026 级 EE 培养方案；后续选修为学习建议，按 2026–2027 开课季节排列。表中的“或”表示按兴趣选支线，不是建议同学期把所有课都选上。</p><table tabindex="0"><thead><tr><th>学期</th><th>课程</th><th>为什么放在这里</th></tr></thead><tbody><tr><td>大一秋</td><td>数学分析 I、线性代数；SI100B</td><td>学会用方程和程序描述系统</td></tr><tr><td>大一春</td><td>EE111、EE111L；数学分析 II、普通物理 I</td><td>电路定律、动态响应和仪器使用是共同底座</td></tr><tr><td>大二秋或春</td><td>EE115A、EE150/EE150L；同时完成 EE115B</td><td>建立器件电路、频域与系统基础，保留混合信号能力</td></tr><tr><td>大二春或大三秋</td><td>EE130、EE130P；按方案完成物理 II</td><td>为射频、光电与器件分支补电磁学</td></tr><tr><td>大三春</td><td>模拟选 EE112；射频选 EE230；电源选 EE171</td><td>EE112 承接 EE111/EE150 且建议 EE115A；EE230 要求 EE130；EE171 要求 EE111</td></tr><tr><td>大四秋或研究生阶段</td><td>模拟选 EE212；射频选 EE234B；电源选 EE270 或 EE273</td><td>分别深入模拟 IC、天线、变换器建模或高级电能变换</td></tr><tr><td>大四秋或研究生阶段</td><td>按目标考虑 EE291I、EE291H</td><td>用工程设计或板级实践整合知识；先核对项目要求与相关基础</td></tr></tbody></table>',6)),o(e,{codes:"EE111,EE111L,EE115A,EE115B,EE150,EE150L,EE130,EE130P,EE112,EE212,EE230,EE234B,EE171,EE270,EE273,EE291I,EE291H"}),a[1]||(a[1]=t('<div class="info custom-block"><p class="custom-block-title">进阶课的条件不同</p><p>EE212 要求 EE112、EE150；EE234B 要求 EE130、EE111；EE273 要求 EE171，而 EE270 的官方先修列为 EE111。EE291H 列有 EE111、EE115A、EE115B、EE171、EE114，不要因为课程名是“实践”就跳过这些条件。EE291I 先修栏留空，也不等于完全无需模拟基础；项目要求以大纲为准。</p></div><h2 id="三条支线怎样选择" tabindex="-1">三条支线怎样选择 <a class="header-anchor" href="#三条支线怎样选择" aria-label="Permalink to &quot;三条支线怎样选择&quot;">​</a></h2><h3 id="模拟与混合信号" tabindex="-1">模拟与混合信号 <a class="header-anchor" href="#模拟与混合信号" aria-label="Permalink to &quot;模拟与混合信号&quot;">​</a></h3><p>从简单放大器开始，把偏置、增益、带宽、稳定性、噪声与功耗联系起来。进入集成电路设计后，需要理解工艺角、失配、寄生和版图匹配。设计 ADC、PLL 或接口电路前，应先能独立解释基础模块的工作点与反馈回路。</p><h3 id="射频与电磁" tabindex="-1">射频与电磁 <a class="header-anchor" href="#射频与电磁" aria-label="Permalink to &quot;射频与电磁&quot;">​</a></h3><p>当电路尺度、频率和传播效应使集中参数近似不再充分时，需要传输线、散射参数、阻抗匹配和电磁仿真。射频并不等于“频率更高的模电题”：参考面、端口、校准和封装都会影响结果。</p><h3 id="电源与电力电子" tabindex="-1">电源与电力电子 <a class="header-anchor" href="#电源与电力电子" aria-label="Permalink to &quot;电源与电力电子&quot;">​</a></h3><p>把电路工作状态、磁性元件、控制和热设计连起来。关注效率曲线与工作范围，而不是只报一个峰值效率。板级变换器与片上电源管理有交叉，也有不同的器件、工艺和测试条件。</p><h2 id="校外补充资源" tabindex="-1">校外补充资源 <a class="header-anchor" href="#校外补充资源" aria-label="Permalink to &quot;校外补充资源&quot;">​</a></h2><ul><li><a href="/shanghaitech-ic-wiki-dev.github.io/self-learning/analog">模拟电路自学</a>：按电路分析、晶体管小信号、反馈和噪声循序推进，再读模拟 IC 教材。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/self-learning/device">器件自学</a>：帮助理解阈值、输出电阻、失配与模型适用范围。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/self-learning/foundations">基础资源</a>：补微分方程、复数频域、概率统计与数据处理。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/eda/">EDA 工具</a>：先理解仿真分析类型，再学习脚本和 GUI；不要使用来源不明的 PDK 或许可证。</li></ul><h2 id="可进入的科研方向" tabindex="-1">可进入的科研方向 <a class="header-anchor" href="#可进入的科研方向" aria-label="Permalink to &quot;可进入的科研方向&quot;">​</a></h2><p>对应 <a href="/shanghaitech-ic-wiki-dev.github.io/research/analog-mixed">模拟与混合信号</a>、<a href="/shanghaitech-ic-wiki-dev.github.io/research/rf-em">射频与电磁</a>、<a href="/shanghaitech-ic-wiki-dev.github.io/research/power">电源与电力电子</a>，也可以交叉到 <a href="/shanghaitech-ic-wiki-dev.github.io/research/mems-sensors">传感与 MEMS</a>、<a href="/shanghaitech-ic-wiki-dev.github.io/research/photonics">光电子</a> 和 <a href="/shanghaitech-ic-wiki-dev.github.io/research/devices">器件</a>。从老师公开项目中找出具体指标、系统约束和测量方式，再判断自己需要补哪门课。</p><h2 id="实践建议" tabindex="-1">实践建议 <a class="header-anchor" href="#实践建议" aria-label="Permalink to &quot;实践建议&quot;">​</a></h2><ol><li><strong>分析、仿真、测量各留一份结果</strong>：从低压、低风险电路开始，记录工作点、扫描条件和仪器设置，解释三者不一致的原因。</li><li><strong>进入 IC 项目时做完整检查</strong>：原理图前仿、版图 DRC/LVS、寄生提取与后仿分别回答不同问题；不能用一张典型角波形代替鲁棒性结论。</li><li><strong>竞赛选自己能验证的题目</strong>：可从 <a href="/shanghaitech-ic-wiki-dev.github.io/competitions/">竞赛导航</a> 了解电路与系统实践机会。涉及高压、大电流、激光或昂贵仪器时，必须经过相应安全培训与授权。</li><li><strong>实训不要错配方向</strong>：<a href="/shanghaitech-ic-wiki-dev.github.io/courses/cadence-summer">Cadence 暑期实训</a> 的往届主线偏数字后端，可帮助理解通用实现流程，但不能替代模拟设计训练。<a href="/shanghaitech-ic-wiki-dev.github.io/competitions/ysyx">一生一芯</a> 偏数字处理器，也不是模拟路线必修项。</li></ol><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://sist.shanghaitech.edu.cn/2833/list.htm" target="_blank" rel="noreferrer">学院本科生培养</a>：2026 级 EE 方案基础学期，依据官方本地摘录整理。</li><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">2026–2027 学年开课表</a>：课程名称、季节及先修。</li><li><a href="https://sist.shanghaitech.edu.cn/2835/list.htm" target="_blank" rel="noreferrer">学院本硕博课程体系</a>。研究生课程与工程项目的本科选修资格，以当学期规定为准。</li></ul>',16))])}const p=i(d,[["render",s]]);export{b as __pageData,p as default};
